const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const I=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
let stored={};try{stored=JSON.parse(localStorage.getItem('nextstep-student-v1')||'{}')}catch{}
const state={profile:null,completed:[],learned:[],dates:[],projects:[],resume:{},...stored};let page='home',onboardStep=0,draft=state.profile?{...state.profile}:{name:'',course:'Computer Science / IT',degree:'B.Tech / B.E. CSE or IT',year:'First year',domain:'',language:'Not sure yet'},lessonIndex=0,lessonPhase='concept',timer=null,remaining=300,timed=false,feedback='',motion=true;
try{motion=localStorage.getItem('nextstep-motion-v3')!=='off'}catch{}
const save=()=>{try{localStorage.setItem('nextstep-student-v1',JSON.stringify(state))}catch{notify('Storage unavailable. This session will still work.')}};
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function streak(){const days=new Set(state.dates);let d=new Date(),n=0;if(!days.has(localDay(d)))d.setDate(d.getDate()-1);while(days.has(localDay(d))){n++;d.setDate(d.getDate()-1)}return n}
const domain=()=>state.profile?.domain||draft.domain;const key=(i,d=domain())=>`${d}:${i}`;const complete=i=>state.completed.includes(key(i));const progress=()=>GUIDES[domain()]?GUIDES[domain()].lessons.filter((_,i)=>complete(i)).length:0;
const nextLesson=()=>{const g=GUIDES[domain()];return g?g.lessons.findIndex((_,i)=>!complete(i)):-1};
const external=(url,label)=>`<a class="external" href="${url}" target="_blank" rel="noopener noreferrer">${label} ${I('arrow-up-right')}</a>`;
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(notify.id);notify.id=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function icons(){window.lucide?.createIcons()}
function info(d=domain()){if(GUIDES[d])return GUIDES[d];return {icon:'compass',outcome:OVERVIEWS[d]?.[0]||`Explore the foundations, work, and prerequisites of ${d}.`,skills:OVERVIEWS[d]?.[1]||['Role research','Relevant foundations','Practical evidence','Communication'],stages:['Understand the role and its work','Check prerequisites with a subject mentor','Choose a reliable learning resource','Plan a small relevant project','Document feedback and next steps'],project:[`${d}: a local problem study`,`Investigate one real campus or community problem relevant to ${d}. Define what you can evaluate and ask a subject mentor to review the scope.`,`Write a problem brief; gather consent-based evidence; create a small demonstration; document feedback and limitations.`]}}
function layout(){document.body.classList.toggle('quiet',!motion);if(!state.profile){onboarding();return}const names={home:'Your learning space',roadmap:'Your roadmap',explore:'Explore directions',projects:'Your project journal',opportunities:'Possibilities ahead',resume:'Resume studio'};$('#app').innerHTML=`<aside><a class="brand" href="#" data-go="home">${window.NextStepBrand.mark()}<span class="nextstep-wordmark">${window.NextStepBrand.wordmark()}</span></a><div class="nav-caption">YOUR NEXT CHAPTER</div><nav>${[['home','layout-dashboard','Overview'],['roadmap','route','My roadmap'],['explore','compass','Explore paths'],['projects','folder-kanban','My projects'],['opportunities','telescope','Opportunities'],['resume','file-user','Resume studio']].map(([id,ic,t])=>`<button data-go="${id}" class="${page===id?'active':''}">${I(ic)}<span>${t}</span>${page===id?'<b></b>':''}</button>`).join('')}</nav><div class="sidebar-message"><span class="small-label">A NOTE TO YOUR FUTURE SELF</span><p>Confidence comes<br>from <em>doing.</em></p><small>We’ll help you understand the next step.</small></div><button class="profile-button" id="edit-profile"><b>${esc(state.profile.name[0].toUpperCase())}</b><span>${esc(state.profile.name)}<small>${esc(state.profile.year)} · Edit profile</small></span>${I('settings-2')}</button></aside><div class="workspace"><header><span>Workspace <span class="slash">/</span> ${names[page]}</span><div><span class="local-label">FRONTEND PREVIEW</span><button id="motion" class="icon-button" aria-label="${motion?'Pause':'Enable'} visual motion" aria-pressed="${motion}">${I(motion?'pause':'play')}</button><button class="course-button" id="edit-profile-top">${I('graduation-cap')}${esc(state.profile.course)}</button></div></header><main id="main" class="chapter-view chapter-${page}" tabindex="-1">${({home:home,roadmap:roadmap,explore:explore,projects:projects,opportunities:opportunities,resume:resume})[page]()}</main><footer><span>Learn with purpose. Build with confidence.</span><span>Introductory content · Subject review pending · Saved on this device</span></footer></div>`;icons();bind();}
function heading(k,h,p){return `<div class="page-heading"><div><span class="small-label">${k}</span><h1>${h}</h1><p>${p}</p></div></div>`}
function onboarding(){const domains=COURSES[draft.course].domains;if(!domains.includes(draft.domain))draft.domain=domains[0];$('#app').innerHTML=`<div class="onboard"><section class="intro"><a class="brand" href="#">${window.NextStepBrand.mark()}<span class="nextstep-wordmark">${window.NextStepBrand.wordmark()}</span></a><div class="intro-copy"><span class="small-label">YOUR POTENTIAL. A CLEARER DIRECTION.</span><h1>A future you<br>can <em>build.</em></h1><p>Find a career direction that fits your course. Understand the concepts, practise with guidance, and turn your learning into work you’re proud to show.</p><div class="intro-flow"><div><b>01</b><span>Find your direction<small>Paths that connect to your course</small></span></div><div><b>02</b><span>Understand, then practise<small>Concept → example → challenge</small></span></div><div><b>03</b><span>Make your progress tangible<small>Projects, a portfolio, and your resume</small></span></div></div></div><div class="intro-bottom"><span>BUILT FOR STUDENTS, AT THEIR OWN PACE</span><span>01 — THE BEGINNING</span></div></section><section class="onboard-form"><div class="onboard-top"><span>${state.profile?'EDIT YOUR JOURNEY':'LET’S MAKE THIS PERSONAL'}</span><span>STEP ${onboardStep+1} OF 2</span></div><div class="step-lines"><i class="filled"></i><i class="${onboardStep?'filled':''}"></i></div>${onboardStep===0?`<h2>First, a little<br>about <em>you.</em></h2><p>Tell us where you are. We’ll help you decide what comes next.</p><form id="profile-form"><label>Your name<input name="name" required maxlength="50" autocomplete="given-name" placeholder="What should we call you?" value="${esc(draft.name)}"></label><label>Your course area<select name="course" id="course-select">${Object.keys(COURSES).map(c=>`<option ${c===draft.course?'selected':''}>${c}</option>`).join('')}</select></label><div class="form-grid"><label>Degree / programme<select name="degree" id="degree-select">${COURSES[draft.course].degrees.map(d=>`<option ${d===draft.degree?'selected':''}>${d}</option>`).join('')}</select></label><label>Current year<select name="year">${['First year','Second year','Third year','Final year','Postgraduate','Other'].map(y=>`<option ${y===draft.year?'selected':''}>${y}</option>`).join('')}</select></label></div><button class="primary full">Find my directions ${I('arrow-right')}</button>${state.profile?'<button class="text-button full" type="button" id="cancel-profile">Back to workspace</button>':''}</form>`:`<h2>Where does your<br><em>curiosity</em> lead?</h2><p>These are starting points related to ${esc(draft.course)}. You can change your direction later.</p><form id="direction-form"><label>Career direction<select name="domain" id="domain-select">${domains.map(d=>`<option ${d===draft.domain?'selected':''}>${d}</option>`).join('')}</select></label><div class="direction-preview" id="direction-preview">${directionPreview(draft.domain)}</div><label>Programming language / technology<input name="language" list="language-list" value="${esc(draft.language)}" placeholder="Search or type your preference"><datalist id="language-list">${LANGUAGES.map(l=>`<option value="${l}">`).join('')}</datalist></label><p class="field-note">Not every path needs programming. This preference is saved; language-specific coding lessons are a later release.</p><button class="primary full">Build my learning space ${I('arrow-right')}</button><button class="text-button full" type="button" id="back-onboard">${I('arrow-left')} Back to your details</button></form>`}<div class="privacy-note">${I('lock-keyhole')} Your profile and progress stay in this browser. No account is created.</div></section></div>`;icons();$('#course-select')?.addEventListener('change',e=>{draft.course=e.target.value;$('#degree-select').innerHTML=COURSES[draft.course].degrees.map(d=>`<option>${d}</option>`).join('')});$('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(draft,Object.fromEntries(new FormData(e.target)));draft.name=draft.name.trim();if(!draft.name){e.target.elements.name.setCustomValidity('Please enter your name.');e.target.elements.name.reportValidity();e.target.elements.name.setCustomValidity('');return}onboardStep=1;onboarding();$('.onboard-form').scrollIntoView({block:'start'})});$('#domain-select')?.addEventListener('change',e=>{draft.domain=e.target.value;$('#direction-preview').innerHTML=directionPreview(draft.domain);icons()});$('#direction-form')?.addEventListener('submit',e=>{e.preventDefault();Object.assign(draft,Object.fromEntries(new FormData(e.target)));state.profile={...draft};save();onboardStep=0;page='home';layout();window.scrollTo(0,0);notify('Your journey starts with understanding. Let’s take the first step.')});$('#back-onboard')?.addEventListener('click',()=>{draft.language=$('[name="language"]').value;onboardStep=0;onboarding()});$('#cancel-profile')?.addEventListener('click',layout)}
function directionPreview(d){const g=info(d);return `${I(g.icon)}<div><strong>${esc(d)}</strong><p>${esc(g.outcome)}</p><small>${GUIDES[d]?'3 guided introductory lessons available':'Career overview available · guided lessons being prepared'}</small></div>`}
function home(){const p=state.profile,g=info(),next=nextLesson(),n=progress();return `${heading('YOUR FUTURE, ONE STEP AT A TIME',`Welcome to your next chapter, <em>${esc(p.name)}.</em>`,`You’re exploring ${esc(domain())}. Here’s how we’ll help you move forward.`)}<section class="welcome-banner"><div><span class="tag light">YOUR LEARNING JOURNEY</span><h2>Understand it.<br>Try it. <em>Make it yours.</em></h2><p>${GUIDES[domain()]?'Every lesson explains the why, teaches the concept, and walks through an example. The challenge comes only when you’re ready.':'Start by exploring what this domain involves. Guided lessons for this direction are still being prepared; use a mentor to help assess prerequisites.'}</p><button class="primary" ${GUIDES[domain()]?`data-lesson="${next<0?0:next}"`:'data-go="roadmap"'}>${next<0&&GUIDES[domain()]?'Revisit your learning':'Show me my next step'} ${I('arrow-up-right')}</button></div><div class="journey-overview"><div><span>01</span><b>Learn the concept</b>${I('book-open')}</div><div><span>02</span><b>See it in action</b>${I('scan-eye')}</div><div><span>03</span><b>Take the challenge</b>${I('flag')}</div><small>YOUR PACE. YOUR PROGRESS.</small></div></section><div class="metrics">${[[I('flame'),streak(),'Day learning streak'],[I('check-check'),state.completed.length,'Tasks completed'],[I('sparkles'),state.completed.length*50,'Learning XP'],[I('folder-kanban'),state.projects.length,'Projects started']].map(([ic,v,l])=>`<div class="metric">${ic}<strong>${v}</strong><span>${l}</span></div>`).join('')}</div><div class="two-col"><section><div class="section-title"><h2>Your next learning step</h2><button class="text-button" data-go="roadmap">Full roadmap ${I('arrow-right')}</button></div><article class="card next-card"><span class="tag">${esc(domain())}</span><h3>${GUIDES[domain()]?esc(g.lessons[next<0?0:next].title):'Understand the work before choosing the path'}</h3><p>${GUIDES[domain()]?esc(g.lessons[next<0?0:next].why):esc(g.outcome)}</p><div class="lesson-meta">${I('book-open')} Concept first <span>·</span> Example included <span>·</span> ${GUIDES[domain()]?'5–10 min':'Career exploration'}</div><div class="progress"><span style="width:${n/3*100}%"></span></div><div class="row-between"><small>${n} of ${GUIDES[domain()]?3:0} introductory lessons completed</small><button class="round-button" ${GUIDES[domain()]?`data-lesson="${next<0?0:next}"`:'data-go="roadmap"'} aria-label="Open next learning step">${I('arrow-up-right')}</button></div></article></section><section><div class="section-title"><h2>Confidence, built on evidence</h2></div><article class="card paper-card"><span class="small-label">A NOTE FOR YOUR JOURNEY</span><h3>You don’t need to know everything.<br><em>Just your next step.</em></h3><p>Try a concept. Ask a question. Make a small improvement. Keep a record of the work you can explain.</p><button class="text-button" data-go="projects">Start a project journal ${I('arrow-right')}</button></article></section></div>`}
function roadmap(){const g=info(),guided=!!GUIDES[domain()];return `${chapterHero('roadmap',{kicker:'01 / YOUR LEARNING ROADMAP',title:`One clear step.<br><em>A stronger direction.</em>`,description:esc(g.outcome),tag:esc(domain()),metric:guided?`${progress()}<small> / ${g.lessons.length}</small>`:'OVERVIEW',label:guided?'introductory lessons completed':'Guided lessons in preparation',action:guided?`<button class="primary" data-lesson="${nextLesson()<0?0:nextLesson()}">${progress()===g.lessons.length?'Revisit the foundations':'Continue your learning'} ${I('arrow-up-right')}</button>`:'<button class="primary" data-go="explore">Compare directions '+I('arrow-up-right')+'</button>'})}${chapterMethod()}<div class="notice">${I('info')} This is a starting framework, not a complete qualification. The introductory lessons are samples; later stages need subject review and deeper practice.</div><div class="two-col roadmap-layout"><section class="card"><div class="section-title"><h2>Your learning sequence</h2><span class="tag">${esc(state.profile.year)}</span></div>${g.stages.map((s,i)=>`<div class="roadmap-stage ${i===0?'active-stage':''}"><span class="stage-no">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(s)}</h3><p>${i===0&&guided?'Start here: understand three core ideas with examples and challenges.':i===0?'Explore the role, typical work, and prerequisites with a subject mentor.':'Planned deeper-learning stage · not available as a lesson yet'}</p></div></div>`).join('')}</section><section><h2 class="compact-title">${guided?'Start with the foundations':'Make an informed start'}</h2>${guided?g.lessons.map((l,i)=>{let open=i===0||complete(i-1);return `<article class="card lesson-card ${!open?'locked':''}"><span class="tag">${complete(i)?'COMPLETED':open?'READY TO LEARN':'NEXT IN SEQUENCE'}</span><h3>${esc(l.title)}</h3><p>${esc(l.why)}</p><button class="${open?'primary':'secondary'}" ${open?`data-lesson="${i}"`:'disabled'}>${I(complete(i)?'rotate-ccw':open?'book-open':'lock-keyhole')}${complete(i)?'Review concept':open?'Learn this concept':'Complete the previous lesson'}</button></article>`}).join(''):`<article class="card"><h3>Your guided course is in preparation.</h3><p>We won’t substitute an unrelated roadmap. Discuss prerequisites and suitable resources with a teacher or domain mentor.</p><button class="primary" data-go="explore">Explore related options ${I('arrow-right')}</button></article>`}<article class="card source-card"><h3>Go deeper with a primary resource</h3>${guided?external(g.source[1],g.source[0]):'<p>Ask a subject teacher to help select a reliable foundational resource for this direction.</p>'}<p>Check prerequisites and fit before committing time or money.</p></article></section></div>`}
function explore(){const c=COURSES[state.profile.course];return `${chapterHero('explore',{kicker:'02 / EXPLORE YOUR POSSIBILITIES',title:`Many directions.<br><em>Find your north.</em>`,description:'Discover how your course connects to different kinds of work. Follow your curiosity, compare the skills, and choose a starting point.',tag:esc(state.profile.course),metric:`${c.domains.length}`,label:'related directions in this course',action:'<a class="primary" href="#explore-filters">Find your direction '+I('arrow-down')+'</a>'})}<div class="chapter-section-heading"><div><span class="small-label">YOUR DOMAIN GALLERY</span><h2>A path that feels like you.</h2></div><span class="chapter-note">Explore freely. You can change your direction.</span></div><div class="filter-bar" id="explore-filters"><label>Explore course area<select id="explore-course">${Object.keys(COURSES).map(x=>`<option ${x===state.profile.course?'selected':''}>${x}</option>`).join('')}</select></label><label>Find a domain<input id="domain-search" type="search" placeholder="Search domains…"></label></div><div class="notice">${I('compass')} These are related directions, not guaranteed eligibility. Professional and regulated roles may require further qualifications.</div><div class="domain-grid" id="domain-grid">${domainCards(state.profile.course)}</div>`}
function domainCards(course,query=''){const ds=COURSES[course].domains.filter(d=>d.toLowerCase().includes(query.toLowerCase()));return ds.length?ds.map((d,i)=>{const g=info(d);return `<article class="card domain-card ${d===domain()?'is-current':''}" style="--card-order:${i%6}"><div class="domain-card-top"><span class="domain-symbol">${I(g.icon)}</span><span class="domain-index" aria-hidden="true">${String(i+1).padStart(2,'0')}</span></div><span class="tag">${GUIDES[d]?'GUIDED INTRO AVAILABLE':'CAREER OVERVIEW'}</span><h3>${d}</h3><p>${esc(g.outcome)}</p><div class="chips">${g.skills.slice(0,3).map(s=>`<span>${s}</span>`).join('')}</div><button class="text-button" data-domain="${d}" data-course="${course}">${d===domain()?'Your current direction':'Explore this direction'} ${I('arrow-up-right')}</button></article>`}).join(''):'<div class="card"><p>No matching domains. Try another term.</p></div>'}
function opportunities(){const g=info();return `${chapterHero('opportunities',{kicker:'04 / TURN LEARNING INTO POSSIBILITY',title:`Build the evidence.<br><em>Open new doors.</em>`,description:'An opportunity begins with something you can explain, demonstrate, and improve. Discover the experiences you can prepare for.',tag:esc(domain()),metric:'04',label:'ways to put your knowledge to work',action:'<button class="primary" data-go="projects">Build something to show '+I('arrow-up-right')+'</button>'})}<div class="opportunity-disclaimer">${I('info')} Preparation pathways, not live vacancies. Check organisers’ current eligibility, terms, and deadlines.</div><div class="chapter-section-heading"><div><span class="small-label">YOUR NEXT HORIZON</span><h2>Where could your work take you?</h2></div></div><div class="domain-grid">${[['Internship applications','briefcase-business',`A small ${domain()} project, a clear explanation of your contribution, and the skills listed by the employer.`,'Build a project and practise explaining one decision.','projects'],['Hackathons & challenges','flag','A scoped idea, a team plan, and a working demonstration. Rules and domain fit vary.','Turn a local problem into a small testable prototype.','projects'],['Research & faculty projects','microscope','Curiosity, a focused question, careful notes, and the prerequisites set by a supervisor.','Prepare a question and a one-page project brief.','roadmap'],['Open-source & community work','git-pull-request','A respectful contribution that follows the project’s guidelines. Documentation can be a starting point.','Practise reading instructions and explaining a change.','roadmap']].map(([t,ic,req,next,go],i)=>`<article class="card opportunity-card opportunity-${i}"><div class="opportunity-art" aria-hidden="true"><span class="opportunity-orbit"></span>${I(ic)}<span class="opportunity-index">0${i+1}</span></div><span class="tag">POSSIBILITY TO EXPLORE</span><h3>${t}</h3><p>${esc(req)}</p><div class="next-action"><small>YOUR NEXT ACTION</small><p>${next}</p></div><button class="text-button" data-go="${go}">Prepare for this ${I('arrow-right')}</button></article>`).join('')}</div><div class="card section-space"><h3>Know where to look</h3><p>Start with your college placement cell, faculty, and employers’ original career pages. Ask who is organising an event, what it costs, what data it collects, and what you will actually do.</p><button class="secondary" data-go="resume">Strengthen your application evidence ${I('arrow-right')}</button></div>`}
function resume(){const g=info(),certs=certificationFor(domain()),r=state.resume;return `${heading('BUILD THE EVIDENCE. THEN TELL THE STORY.',`A resume with <em>substance.</em>`,'Strong applications are specific and truthful. Start with work you can demonstrate, then create your draft.')}<div class="resume-steps"><span><b>01</b> Strengthen skills</span><span><b>02</b> Build evidence</span><span><b>03</b> Write clearly</span></div><div class="two-col"><section><article class="card"><span class="tag">SKILLS TO DEVELOP · ${esc(domain())}</span><h3>Make your next skill visible.</h3><div class="chips">${g.skills.map(s=>`<span>${s}</span>`).join('')}</div><p>Completion of an introductory check is a learning milestone. Add a skill to your resume only when you can demonstrate it and explain your work.</p><button class="text-button" data-go="roadmap">Build these foundations ${I('arrow-right')}</button></article><article class="card section-space"><span class="tag">A PROJECT TO MAKE YOUR OWN</span><h3>${esc(g.project[0])}</h3><p>${esc(g.project[1])}</p><button class="text-button" data-go="projects">See the brief and evidence checklist ${I('arrow-right')}</button></article><article class="card section-space"><span class="tag">CREDENTIALS TO CONSIDER</span>${certs.length?certs.map(([name,why,cost,url])=>`<h3>${name}</h3><p>${why}</p><small>${cost}</small><div style="margin-top:14px">${external(url,'Check the official provider')}</div>`).join(''):'<h3>Choose credentials after choosing your target work.</h3><p>There is no universal best certificate. Check relevant job requirements and discuss a recognised qualification with a subject mentor before paying.</p>'}<p class="field-note">Review the official provider’s current requirements, fees, and terms. Credentials support, rather than guarantee, career outcomes.</p></article></section><section><article class="card resume-builder"><span class="small-label">YOUR PROFESSIONAL DRAFT</span><h2>Let your real work speak.</h2><p>Use specific contributions. Leave out claims you cannot support.</p><form id="resume-form"><label>Contact details<input name="contact" value="${esc(r.contact)}" placeholder="Email · city · portfolio"></label><label>Education<input name="education" value="${esc(r.education||state.profile.degree)}" placeholder="Degree, institution, expected graduation"></label><label>Skills you can demonstrate<input name="skills" value="${esc(r.skills)}" placeholder="Only skills you can explain"></label><label>Project title<input name="title" value="${esc(r.title)}" placeholder="Your own project title"></label><label>What did you personally do?<textarea name="contribution" placeholder="Describe your contribution, tools, and decisions">${esc(r.contribution)}</textarea></label><label>What evidence or result supports it?<textarea name="result" placeholder="Tests, observed feedback, or measured results. Do not invent numbers.">${esc(r.result)}</textarea></label><label>Completed certifications<textarea name="certifications" placeholder="Actual credential, issuer, completion date; optional">${esc(r.certifications)}</textarea></label><div class="button-row"><button class="primary">Save & preview ${I('arrow-right')}</button><button type="button" class="secondary" id="print-resume">Print / PDF ${I('download')}</button></div></form></article></section></div><article class="resume-sheet" id="resume-sheet"><h2>${esc(state.profile.name)}</h2><p>${esc(r.contact||'Add your contact details')}</p><h3>Education</h3><p>${esc(r.education||state.profile.degree)}</p>${r.skills?`<h3>Skills</h3><p>${esc(r.skills)}</p>`:''}${r.title||r.contribution?`<h3>Project experience</h3><h4>${esc(r.title||'Project')}</h4><p>${esc(r.contribution)}</p>${r.result?`<p>${esc(r.result)}</p>`:''}`:''}${r.certifications?`<h3>Certifications</h3><p>${esc(r.certifications)}</p>`:''}<small class="draft-only">Editable draft · Review all details before sharing.</small></article>`}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();page=b.dataset.go;layout();window.scrollTo(0,0)});$('#edit-profile').onclick=editProfile;$('#edit-profile-top').onclick=editProfile;$('#motion').onclick=()=>{motion=!motion;document.querySelectorAll('.scene-sweep,.cinema-spark,.cinema-pulse,.click-wave').forEach(el=>el.remove());try{localStorage.setItem('nextstep-motion-v3',motion?'on':'off')}catch{}document.body.classList.toggle('quiet',!motion);$('#motion').setAttribute('aria-label',`${motion?'Pause':'Enable'} visual motion`);$('#motion').setAttribute('aria-pressed',motion);$('#motion').innerHTML=I(motion?'pause':'play');icons()};document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)));bindDomains();bindProjectSteps();const updateDomains=()=>{const course=$('#explore-course').value;$('#domain-grid').innerHTML=domainCards(course,$('#domain-search').value);$('#explore-hero-course').textContent=course;$('#explore-hero-count').textContent=COURSES[course].domains.length;icons();bindDomains()};$('#explore-course')?.addEventListener('change',updateDomains);$('#domain-search')?.addEventListener('input',updateDomains);$('#start-project')?.addEventListener('click',()=>{const g=info();const existing=state.projects.findIndex(p=>p.domain===domain());if(existing>=0){document.querySelector(`#project-${existing}`).scrollIntoView({block:'start',behavior:motion?'smooth':'auto'});return}state.projects.push({title:g.project[0],domain:domain(),steps:[false,false,false,false],evidence:''});save();layout();document.querySelector(`#project-${state.projects.length-1}`).scrollIntoView({block:'start',behavior:motion?'smooth':'auto'});notify('Project started. Open step 1 to see exactly what to do.')});document.querySelectorAll('[data-project]').forEach(c=>c.onchange=()=>{state.projects[c.dataset.project].steps[c.dataset.step]=c.checked;save();layout()});document.querySelectorAll('[data-evidence]').forEach(e=>e.onchange=()=>{if(e.value&&!e.checkValidity()){e.reportValidity();return}state.projects[e.dataset.evidence].evidence=e.value.trim();save();notify('Evidence link saved')});$('#resume-form')?.addEventListener('submit',e=>{e.preventDefault();state.resume=Object.fromEntries(new FormData(e.target));save();layout();$('#resume-sheet').scrollIntoView({behavior:motion?'smooth':'auto'});notify('Draft updated using your own details.')});$('#print-resume')?.addEventListener('click',()=>{const f=$('#resume-form');state.resume=Object.fromEntries(new FormData(f));save();layout();window.print()})}
function bindDomains(){document.querySelectorAll('[data-domain]').forEach(b=>b.onclick=()=>{const d=b.dataset.domain,c=b.dataset.course;$('#modal-title').textContent=d;const g=info(d);$('#modal-body').innerHTML=`<span class="tag">${esc(c)}</span><h3>${esc(g.outcome)}</h3><p>Relevant skills to explore:</p><div class="chips">${g.skills.map(s=>`<span>${s}</span>`).join('')}</div><p>${GUIDES[d]?'This direction includes three introductory concept-first lessons. Deeper stages remain a learning framework.':'This direction has an overview only. Guided domain lessons are not yet available.'}</p><p>Changing direction keeps previous learning progress. If you choose a different course area, it updates your profile too; you can edit your degree afterward.</p><button class="primary" id="select-domain">Choose this direction ${I('arrow-right')}</button>`;$('#modal').showModal();icons();$('#select-domain').onclick=()=>{state.profile.domain=d;if(c!==state.profile.course){state.profile.course=c;state.profile.degree=COURSES[c].degrees[0]}save();$('#modal').close();page='roadmap';layout()}})}
function editProfile(){draft={...state.profile};onboardStep=0;onboarding();window.scrollTo(0,0)}
function clearTimer(){if(timer)clearInterval(timer);timer=null}
function openLesson(i){const g=GUIDES[domain()];if(!g||i<0||i>=g.lessons.length||i>0&&!complete(i-1))return;clearTimer();lessonIndex=i;lessonPhase='concept';feedback='';timed=false;remaining=300;$('#modal').showModal();renderLesson()}
function renderLesson(){const l=GUIDES[domain()].lessons[lessonIndex],title=`${lessonIndex+1}. ${l.title}`;$('#modal-title').textContent=title;$('#modal-body').innerHTML=`<div class="lesson-stepper"><span class="${lessonPhase==='concept'?'current':''}">01 Learn</span><span class="${lessonPhase==='example'?'current':''}">02 Understand</span><span class="${lessonPhase==='challenge'?'current':''}">03 Practise</span></div>${lessonPhase==='concept'?`<span class="tag">WHY THIS TASK MATTERS</span><h3>${esc(l.why)}</h3><h4>The concept</h4><p class="concept-text">${esc(l.concept)}</p><div class="notice subtle">Take your time. There is no timer while you are learning.</div><button class="primary" id="see-example">Show me how it works ${I('arrow-right')}</button>`:lessonPhase==='example'?`<span class="tag">A WORKED EXAMPLE</span><div class="worked-example"><p>${esc(l.example)}</p></div><h4>What to do next</h4><ol><li>Explain the idea to yourself in your own words.</li><li>Notice why the example uses this approach.</li><li>When ready, apply it to a small scenario.</li></ol><p>The challenge checks this concept. You can return to the explanation at any time.</p><label class="timer-choice"><input type="checkbox" id="timed-choice" ${timed?'checked':''}>Try a 5-minute challenge timer (optional)</label><div class="button-row"><button class="primary" id="understand">I understand — I can do it ${I('arrow-right')}</button><button class="text-button" id="read-again">Read the concept again</button></div>`:`<div class="challenge-top"><span class="tag">APPLY WHAT YOU LEARNED</span>${timed?'<span class="challenge-clock" id="challenge-clock">05:00</span>':'<span class="field-note">Untimed practice</span>'}</div><h3>${esc(l.q)}</h3><form id="answer-form"><fieldset><legend class="sr-only">Choose your answer</legend>${l.answers.map((a,i)=>`<label class="answer-option"><input type="radio" name="answer" value="${i}" required><span>${esc(a)}</span></label>`).join('')}</fieldset><div id="answer-feedback" role="status">${feedback}</div><div class="button-row"><button class="primary" id="submit-answer">Check my understanding ${I('check')}</button><button type="button" class="text-button" id="back-example">Back to the explanation</button></div></form>`}`;icons();$('#see-example')?.addEventListener('click',()=>{lessonPhase='example';renderLesson()});$('#read-again')?.addEventListener('click',()=>{timed=$('#timed-choice').checked;lessonPhase='concept';renderLesson()});$('#understand')?.addEventListener('click',()=>{timed=$('#timed-choice').checked;if(!state.learned.includes(key(lessonIndex)))state.learned.push(key(lessonIndex));save();lessonPhase='challenge';renderLesson();if(timed)startTimer()});$('#back-example')?.addEventListener('click',()=>{clearTimer();lessonPhase='example';feedback='';renderLesson()});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();if(Number(new FormData(e.target).get('answer'))!==l.correct){$('#answer-feedback').innerHTML=`<div class="feedback retry"><strong>Let’s work through that.</strong><p>${esc(l.explanation)}</p><small>Review the explanation or try again. Your progress isn’t lost.</small></div>`;return}clearTimer();const id=key(lessonIndex),fresh=!state.completed.includes(id);if(fresh){state.completed.push(id);const today=localDay();if(!state.dates.includes(today))state.dates.push(today);save()}$('#answer-feedback').innerHTML=`<div class="feedback success"><strong>${I('check-circle-2')} Concept applied. Well done.</strong><p>${esc(l.explanation)}</p><div class="reward-row"><span>${fresh?'+50':'Already earned'} XP</span><span>${streak()} day learning streak</span></div><small>A knowledge check is a milestone, not a full assessment of practical competence.</small></div><button class="primary full" type="button" id="next-concept">${lessonIndex<2?'Continue to the next concept':'See your progress'} ${I('arrow-right')}</button>`;$('#submit-answer').disabled=true;icons();$('#next-concept').onclick=()=>{if(lessonIndex<2){lessonIndex++;lessonPhase='concept';timed=false;remaining=300;renderLesson()}else{$('#modal').close();page='roadmap';layout()}};layout()});$('#modal-body').scrollTop=0;$('#modal').scrollTop=0}
function startTimer(){remaining=300;const update=()=>{const el=$('#challenge-clock');if(el)el.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`};update();timer=setInterval(()=>{remaining--;update();if(remaining<=0){clearTimer();$('#challenge-clock').textContent='Time complete';$('#answer-feedback').innerHTML='<div class="feedback retry"><strong>Time is up. Keep learning at your pace.</strong><p>You can continue this attempt untimed. No progress is removed.</p></div>'}},1000)}
$('#modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{clearTimer();if(state.profile)layout()});document.addEventListener('click',e=>{if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!motion)return;const target=e.target instanceof Element?e.target:document.body;const r=document.createElement('span');r.className='click-wave';r.setAttribute('aria-hidden','true');const rect=target.getBoundingClientRect();let x=e.detail===0?rect.left+rect.width/2:e.clientX,y=e.detail===0?rect.top+rect.height/2:e.clientY;const dialog=target.closest('dialog[open]');if(dialog&&getComputedStyle(dialog).transform!=='none'){const box=dialog.getBoundingClientRect();x-=box.left;y-=box.top}r.style.left=x+'px';r.style.top=y+'px';(dialog||document.body).appendChild(r);r.addEventListener('animationend',()=>r.remove(),{once:true});setTimeout(()=>r.remove(),800)});document.body.classList.toggle('quiet',!motion);if(new URLSearchParams(location.search).has('setup'))onboarding();else layout();
